/**
 * Milestone domain rules that do not need the database: the conflict error
 * and the name / overdue predicates the service and repository share.
 */
import type { IsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { IssueStatus } from "@/types/issue";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

/** Raised when a milestone's state (or the project's) forbids the operation. */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: MilestoneStateReason) {
    super(`Milestone conflict: ${reason}`);
    this.name = "MilestoneStateError";
  }
}

/** Case- and surrounding-space-insensitive form names are compared by. */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

export function isMilestoneOpen(milestone: Pick<Milestone, "closedAt">): boolean {
  return milestone.closedAt === null;
}

export function isClosedIssueStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** Open, dated strictly before `now`, and still holding open issues. */
export function isMilestoneOverdue(
  milestone: Pick<Milestone, "closedAt" | "targetDate">,
  progress: MilestoneProgress,
  now: Date,
): boolean {
  if (milestone.closedAt !== null || milestone.targetDate === null) return false;
  return (
    Date.parse(milestone.targetDate) < now.getTime() && progress.open > 0
  );
}

function stamp(value: IsoTimestamp | null): number {
  return value === null ? Number.POSITIVE_INFINITY : Date.parse(value);
}

/**
 * Open milestones first, then closed; each group by target date (undated
 * last), ties keeping the incoming (creation) order — the sort is stable.
 */
export function sortMilestones<T extends Milestone>(
  milestones: readonly T[],
): readonly T[] {
  return [...milestones].sort((a, b) => {
    const openDelta = Number(a.closedAt !== null) - Number(b.closedAt !== null);
    if (openDelta !== 0) return openDelta;
    const ta = stamp(a.targetDate);
    const tb = stamp(b.targetDate);
    if (ta === tb) return 0;
    return ta < tb ? -1 : 1;
  });
}
