import { and, asc, eq, inArray, isNull, isNotNull, sql } from "drizzle-orm";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { newId } from "@/lib/id";
import { isClosedIssueStatus, MilestoneStateError, milestoneNameKey } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toMilestone } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

type Tx = Parameters<Parameters<ReturnType<typeof getDb>["transaction"]>[0]>[0];

/** An issue moved by a close, with who to tell about it. */
export interface MovedIssue {
  readonly id: IssueId;
  readonly assigneeId: UserId | null;
}

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of a project in creation order (insertion order breaks ties). */
export async function listMilestonesForProject(
  orgId: OrgId,
