  milestoneId: MilestoneId,
  moveTo: MilestoneId | null,
): Promise<{ milestone: Milestone; moved: readonly MovedIssue[] }> {
  const now = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(milestones)
      .where(
        and(
          orgPredicate(milestones.orgId, orgId),
          eq(milestones.id, milestoneId),
        ),
      )
      .get();
    if (!current) throw new Error(`Milestone ${milestoneId} not found`);
    if (current.closedAt !== null) throw new MilestoneStateError("closed");

    if (moveTo !== null) {
      const target = tx
        .select()
        .from(milestones)
        .where(
          and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, moveTo)),
        )
        .get();
      if (!target) throw new Error(`Milestone ${moveTo} not found`);
      if (target.closedAt !== null) throw new MilestoneStateError("closed");
    }

    const candidates = tx
      .select({
        id: issues.id,
        status: issues.status,
        assigneeId: issues.assigneeId,
      })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.milestoneId, milestoneId),
          isNull(issues.archivedAt),
        ),
      )
      .all()
      .filter((row) => !isClosedIssueStatus(row.status));

    if (candidates.length > 0) {
      tx.update(issues)
        .set({ milestoneId: moveTo, updatedAt: now })
        .where(
          and(
            orgPredicate(issues.orgId, orgId),
            inArray(
              issues.id,
              candidates.map((row) => row.id),
            ),
          ),
        )
        .run();
    }

    const row = tx
      .update(milestones)
      .set({ closedAt: now, updatedAt: now })
      .where(
        and(
          orgPredicate(milestones.orgId, orgId),
          eq(milestones.id, milestoneId),
        ),
      )
      .returning()
      .get();

    return {
      milestone: toMilestone(row),
      moved: candidates.map((issue) => ({
        id: issue.id as IssueId,
        assigneeId: (issue.assigneeId as UserId | null) ?? null,
      })),
    };
  });
}

