    if (!current) throw new Error(`Milestone ${milestoneId} not found`);
    if (current.closedAt === null) throw new MilestoneStateError("already_open");
    assertRoomForOpen(tx, orgId, current.projectId as ProjectId);

    const row = tx
      .update(milestones)
      .set({ closedAt: null, updatedAt: toIsoTimestamp(new Date()) })
      .where(
        and(
          orgPredicate(milestones.orgId, orgId),
          eq(milestones.id, milestoneId),
        ),
      )
      .returning()
      .get();
    return toMilestone(row);
  });
}

/** Live-issue counts per milestone of a project; absent ids have none. */
export async function getProgressForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ReadonlyMap<MilestoneId, MilestoneProgress>> {
  const rows = getDb()
    .select({ milestoneId: issues.milestoneId, status: issues.status })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        isNotNull(issues.milestoneId),
        isNull(issues.archivedAt),
      ),
    )
    .all();

  const totals = new Map<MilestoneId, { open: number; closed: number }>();
  for (const row of rows) {
    const id = row.milestoneId as MilestoneId;
    const entry = totals.get(id) ?? { open: 0, closed: 0 };
    if (isClosedIssueStatus(row.status)) entry.closed += 1;
    else entry.open += 1;
    totals.set(id, entry);
  }

  return new Map(
    [...totals].map(([id, { open, closed }]) => [
      id,
      { total: open + closed, open, closed },
    ]),
  );
}
