/**
 * Project milestones: lifecycle (create, rename, close, reopen), progress and the events/audit trail they publish.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import { emit } from "@/lib/event-bus";
import { isMilestoneOpen, isMilestoneOverdue, MilestoneStateError, sortMilestones } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { actorEnvelope, projectResource, requireFound } from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";
import type { Project } from "@/types/project";

const NO_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

/** Loads a project and gates a milestone write on `project:update` and a live project. */
async function requireEditableProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return project;
}

/** Same gate for an operation that starts from a milestone id. */
async function requireEditableMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  await requireEditableProject(actor, orgId, milestone.projectId);
  return milestone;
}

function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date,
): MilestoneWithProgress {
  return {
    milestone,
    progress,
    overdue: isMilestoneOverdue(milestone, progress, now),
  };
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  await requireEditableProject(actor, input.orgId, input.projectId);

  const milestone = await milestoneRepo.insertMilestone(
    input.orgId,
    input.projectId,
    input.name,
    input.targetDate ?? null,
